using System.Windows;using System.Windows.Controls;using LibraryManager.Services;using LibraryManager.Data;using LibraryManager.Models;namespace LibraryManager.Views;public partial class LoanRegisterView:UserControl{ComboBox mem,book;TextBlock status;LoanService svc=new();public LoanRegisterView(){InitializeComponent();var p=VH.Page(Root,"ثبت امانت کتاب");using var d=new LibraryDbContext();mem=new ComboBox{ItemsSource=d.Members.ToList(),DisplayMemberPath="LastName",SelectedValuePath="Id",Margin=new Thickness(5)};book=new ComboBox{ItemsSource=d.Books.ToList(),DisplayMemberPath="Title",SelectedValuePath="Id",Margin=new Thickness(5)};p.Children.Add(new TextBlock{Text="عضو",Margin=new Thickness(5)});p.Children.Add(mem);p.Children.Add(new TextBlock{Text="کتاب",Margin=new Thickness(5)});p.Children.Add(book);status=new TextBlock{Margin=new Thickness(8)};p.Children.Add(status);mem.SelectionChanged+=(s,e)=>{if(mem.SelectedValue!=null)status.Text=svc.CanBorrow((int)mem.SelectedValue);};p.Children.Add(VH.Btn("تمدید عضویت",(s,e)=>{if(mem.SelectedValue!=null&&PaymentDialog.ShowPayment("تمدید عضویت")){new MemberService().Renew((int)mem.SelectedValue,12,PaymentDialog.Method);status.Text="عضویت تمدید شد؛ اکنون ثبت امانت را انجام دهید.";}}));p.Children.Add(VH.Btn("ثبت امانت",(s,e)=>{try{if(mem.SelectedValue==null||book.SelectedValue==null)throw new Exception("عضو و کتاب را انتخاب کنید.");var l=svc.Register((int)mem.SelectedValue,(int)book.SelectedValue);MessageBox.Show("امانت ثبت شد. سررسید: "+l.DueDate.ToShortDateString());}catch(Exception ex){VH.Error(ex);}}));}}